const aiRes = JSON.parse($input.first().json.choices[0].message.content);
const lead = $('Normalize Lead Object').first().json;

return [{
  json: {
    lead_id: lead.id,
    fingerprint: lead.fingerprint,
    name: lead.name,
    company_name: lead.company_name,
    target_market: lead.target_market,
    contact_phone: lead.contact_phone,
    contact_whatsapp: lead.contact_whatsapp,
    contact_telegram: lead.contact_telegram,
    contact_instagram: lead.contact_instagram,
    website_url: lead.website_url,
    source: lead.source,
    location_wilaya: lead.location_wilaya,
    ai_fit_score: aiRes.ai_fit_score || 0,
    ai_scoring_reasoning: aiRes.ai_scoring_reasoning || '',
    proposed_service: aiRes.proposed_service || lead.proposed_service,
    ai_pitch_draft: aiRes.ai_pitch_draft || '',
    status: (aiRes.ai_fit_score >= 70) ? 'hitl_pending' : 'scored'
  }
}];
